  // /* Theme variables */
  // :root {
  //   --primary: ${a?"#121212":"#FCFCFC"};
  //   --secondary: ${a?"#FCFCFC":"#121212"};
  //   --text-color: ${a?"#DAFAF4":"#121212"};
  //   --accent-color: #C80808;
